-- Additive migration: savings/spending goals for the PWA home page.
-- Follows the conventions of 20261023000000_webapp.sql (text ids generated by
-- the client and ISO-8601 text updated_at) so the shared tombstone and stale-write
-- triggers keep working. Requires that migration to be applied first.
begin;

create table if not exists public.goals (
  id text primary key, user_id uuid not null references auth.users(id) on delete cascade,
  name text not null check (length(btrim(name)) between 1 and 120),
  target_amount numeric(12, 2) not null check (target_amount > 0),
  current_amount numeric(12, 2) not null default 0 check (current_amount >= 0),
  deadline date,
  updated_at text not null default ''
);

alter table public.goals enable row level security;
-- A restrictive ownership policy also protects installations with older permissive policies.
do $$
begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'goals' and policyname = 'washdog_owner_guard') then
    create policy washdog_owner_guard on public.goals as restrictive for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'goals' and policyname = 'washdog_owner_access') then
    create policy washdog_owner_access on public.goals for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
  end if;
end $$;
grant select, insert, update, delete on public.goals to authenticated;
revoke all on public.goals from anon;

create index if not exists washdog_goals_user_idx on public.goals(user_id);

-- Stale writes are ignored and deletions leave a tombstone, like every other synced table.
drop trigger if exists washdog_00_stale on public.goals;
create trigger washdog_00_stale before insert or update on public.goals for each row execute function public.washdog_ignore_deleted_write();
drop trigger if exists washdog_goal_deleted on public.goals;
create trigger washdog_goal_deleted after delete on public.goals for each row execute function public.washdog_record_deletion();

commit;
